import {APP, LIMITS} from './config.js';
import {ERR, RecordError, isQuotaError} from './errors.js';
import {uuid} from './crypto.js';
import {createGame, invalidateCertification, nowIso} from './record.js';
import {validateAuditEvent,validateDerivedAsset,validateGame,validateRecognitionEnvelope,validateRecognitionJob,validateReconstructionRun,validateSourcePage} from './validators.js';

const STORES=['games','sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents','settings','deviceKeys'];
let dbPromise=null;const listeners=new Set();
const request=req=>new Promise((resolve,reject)=>{req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});
const txDone=tx=>new Promise((resolve,reject)=>{tx.oncomplete=()=>resolve();tx.onabort=()=>reject(tx.error||new Error('IndexedDB transaction aborted'));tx.onerror=()=>reject(tx.error||new Error('IndexedDB transaction failed'));});
function auditEvent(game,eventType,payload={},actor='USER'){return {id:uuid(),schema:APP.auditSchema,gameId:game.id,revision:game.revision,timestamp:nowIso(),eventType,actor,payload};}
function putAudit(store,event){validateAuditEvent(event);store.put(event);}
async function getAll(store,indexName=null,key=null){return indexName?request(store.index(indexName).getAll(key)):request(store.getAll());}

export function transformV2Game(old){
  if(old?.schema!=='record-game/2')return old;
  return {id:old.id,schema:APP.gameSchema,recordType:'PLAYED_GAME',createdAt:old.createdAt,updatedAt:nowIso(),revision:Number(old.revision||0)+1,sourceRevision:Number(old.sourceRevision||0),workflowState:old.moves?.length?'READY_FOR_REVIEW':'CAPTURED',certificationStatus:'INVALIDATED',metadata:{...old.metadata,resultProvenance:old.metadata?.resultProvenance||'UNKNOWN'},startFen:old.startFen,moves:(old.moves||[]).map((m,i)=>({...m,ply:i+1})),notes:old.notes||'',certification:null,flags:{needsReview:true}};
}
export function transformV2Source(old){if(old?.schema!=='record-source-page/2')return old;return {...old,schema:APP.sourceSchema,declaredMime:old.mime,detectedMime:old.mime,animated:false,updatedAt:nowIso()};}
export function transformV2Derived(old){if(old?.schema!=='record-derived-asset/1')return old;return {...old,schema:APP.derivedSchema};}
export function transformV2Job(old,runSequence=1){if(old?.schema!=='record-recognition-job/1')return old;return {...old,schema:APP.recognitionJobSchema,runSequence,runKind:'INITIAL',supersedesRequestId:null,status:['UPLOADING','PROCESSING'].includes(old.status)?'FAILED_RETRYABLE':old.status,nextAttemptAt:['UPLOADING','PROCESSING'].includes(old.status)?nowIso():old.nextAttemptAt};}
export function transformV2Observation(old,runSequence=1){if(old?.schema!=='record-recognition-envelope/2')return old;return {...old,schema:APP.recognitionEnvelopeSchema,runSequence,supersedesRequestId:null};}
export function transformV2Audit(old){if(old?.schema!=='record-audit-event/1')return old;return {...old,schema:APP.auditSchema};}

export function transformLegacyV1Game(old){
  if(old?.schema!=='record-game/1')throw new RecordError(ERR.DB_MIGRATION,'Legacy game schema is unsupported.');
  const t=nowIso(),meta=old.metadata||{};return {id:old.id,schema:APP.gameSchema,recordType:'PLAYED_GAME',createdAt:old.createdAt||t,updatedAt:t,revision:1,sourceRevision:0,workflowState:(old.sans?.length||0)?'READY_FOR_REVIEW':'CAPTURED',certificationStatus:'INVALIDATED',metadata:{event:meta.event||'',site:meta.site||'',date:meta.date||'',round:meta.round||'',board:meta.board||'',section:meta.section||'',white:meta.white||'',black:meta.black||'',result:meta.result||'*',timeControl:meta.timeControl||'',resultProvenance:'UNKNOWN'},startFen:old.startFen||'rnbqkbnr/pppppppp/8/8/8/8/PPPPPPPP/RNBQKBNR w KQkq - 0 1',moves:(old.plies||[]).map((p,i)=>({ply:i+1,san:p.san||old.sans?.[i]||'',uci:'',beforeFen:p.before||'',afterFen:p.after||'',provenance:p.provenance||'USER_ENTERED',sourceRefs:p.sourceRef?[p.sourceRef]:[],observationRefs:[]})),notes:old.notes||'',certification:null,flags:{needsReview:true}};
}

function createStores(db){
  if(!db.objectStoreNames.contains('games'))db.createObjectStore('games',{keyPath:'id'});
  if(!db.objectStoreNames.contains('sourcePages')){const s=db.createObjectStore('sourcePages',{keyPath:'id'});s.createIndex('gameId','gameId',{unique:false});}
  for(const name of ['derivedAssets','recognitionJobs','reconstructionRuns','auditEvents'])if(!db.objectStoreNames.contains(name)){const s=db.createObjectStore(name,{keyPath:'id'});s.createIndex('gameId','gameId',{unique:false});}
  if(!db.objectStoreNames.contains('recognitionObservations')){const s=db.createObjectStore('recognitionObservations',{keyPath:'requestId'});s.createIndex('gameId','gameId',{unique:false});}
  for(const name of ['settings','deviceKeys'])if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:'id'});
}
async function openDb(){
  if(dbPromise)return dbPromise;dbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open(APP.dbName,APP.dbVersion);req.onblocked=()=>{listeners.forEach(fn=>fn({type:'blocked'}));reject(new RecordError(ERR.DB_BLOCKED,'Database upgrade is blocked by another RECORD tab. Close other RECORD windows and reload.'));};req.onerror=()=>reject(req.error);req.onupgradeneeded=()=>createStores(req.result);req.onsuccess=()=>{const db=req.result;db.onversionchange=()=>{db.close();dbPromise=null;listeners.forEach(fn=>fn({type:'versionchange'}));};resolve(db);};});return dbPromise;
}
async function withTx(names,mode,fn){const db=await openDb();let tx;try{tx=db.transaction(names,mode,{durability:'strict'});}catch{tx=db.transaction(names,mode);}try{const out=await fn(tx);await txDone(tx);return out;}catch(error){try{tx.abort();}catch{}if(isQuotaError(error))throw new RecordError(ERR.DB_QUOTA,'Browser storage quota was exceeded.');throw error;}}

async function normalizeV2ToV3(){
  const db=await openDb(),tx=db.transaction(STORES.filter(x=>x!=='deviceKeys'),'readwrite');let changed=0;
  const games=await request(tx.objectStore('games').getAll());for(const old of games)if(old?.schema==='record-game/2'){const g=transformV2Game(old);tx.objectStore('games').put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'MIGRATED_V2_TO_V3',{certificationInvalidated:true},'SYSTEM'));changed++;}
  const sources=await request(tx.objectStore('sourcePages').getAll());for(const x of sources)if(x?.schema==='record-source-page/2'){tx.objectStore('sourcePages').put(transformV2Source(x));changed++;}
  const derived=await request(tx.objectStore('derivedAssets').getAll());for(const x of derived)if(x?.schema==='record-derived-asset/1'){tx.objectStore('derivedAssets').put(transformV2Derived(x));changed++;}
  const jobs=await request(tx.objectStore('recognitionJobs').getAll());const seqByPage=new Map();for(const x of jobs.sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt))))if(x?.schema==='record-recognition-job/1'){const seq=(seqByPage.get(x.pageId)||0)+1;seqByPage.set(x.pageId,seq);tx.objectStore('recognitionJobs').put(transformV2Job(x,seq));changed++;}
  const obs=await request(tx.objectStore('recognitionObservations').getAll());for(const x of obs)if(x?.schema==='record-recognition-envelope/2'){const job=jobs.find(j=>j.id===x.requestId),seq=job?seqByPage.get(job.pageId)||1:1;tx.objectStore('recognitionObservations').put(transformV2Observation(x,seq));changed++;}
  const audits=await request(tx.objectStore('auditEvents').getAll());for(const x of audits)if(x?.schema==='record-audit-event/1'){tx.objectStore('auditEvents').put(transformV2Audit(x));changed++;}
  await txDone(tx);return changed;
}

async function legacyDbExists(){if(typeof indexedDB.databases==='function'){try{return (await indexedDB.databases()).some(x=>x.name===APP.legacyDbName);}catch{}}return null;}
async function openExistingLegacy(){
  const exists=await legacyDbExists();if(exists===false)return null;
  return new Promise((resolve,reject)=>{let created=false;const r=indexedDB.open(APP.legacyDbName);r.onupgradeneeded=()=>{created=true;r.transaction.abort();};r.onerror=()=>{if(created||r.error?.name==='AbortError')resolve(null);else reject(r.error);};r.onsuccess=()=>resolve(r.result);});
}
async function readLegacySnapshot(){const db=await openExistingLegacy();if(!db)return null;try{if(!db.objectStoreNames.contains('games')||!db.objectStoreNames.contains('pages'))return null;const tx=db.transaction(['games','pages',...(db.objectStoreNames.contains('settings')?['settings']:[])],'readonly');const games=await request(tx.objectStore('games').getAll()),pages=await request(tx.objectStore('pages').getAll()),settings=db.objectStoreNames.contains('settings')?await request(tx.objectStore('settings').getAll()):[];await txDone(tx);return {games,pages,settings};}finally{db.close();}}

async function commissionLegacyMigration(){
  const prior=await DB.getSetting('legacyFoundationMigrationReceipt',null);if(prior?.status==='COMPLETE')return prior;
  const legacy=await readLegacySnapshot();if(!legacy||(!legacy.games.length&&!legacy.pages.length))return null;
  const {migrateLegacySourcePage}=await import('./image.js');const {parseFen,makeMove}=await import('./chess.js');
  const transformedGames=[],transformedPages=[],derived=[];const pageByGame=new Map();for(const p of legacy.pages){const arr=pageByGame.get(p.gameId)||[];arr.push(p);pageByGame.set(p.gameId,arr);}for(const arr of pageByGame.values())arr.sort((a,b)=>a.order-b.order);
  for(const old of legacy.games){const g=transformLegacyV1Game(old);let state=parseFen(g.startFen),ok=true;for(let i=0;i<g.moves.length;i++){try{const r=makeMove(state,g.moves[i].san);g.moves[i]={...g.moves[i],ply:i+1,uci:r.move.uci,beforeFen:r.move.before,afterFen:r.move.after};state=r.state;}catch{ok=false;break;}}if(!ok)g.flags.needsReview=true;const pp=pageByGame.get(old.id)||[];for(let i=0;i<pp.length;i++){const prepared=await migrateLegacySourcePage(pp[i],{gameId:g.id,order:i});transformedPages.push(prepared.page);derived.push(...prepared.derived);}g.sourceRevision=pp.length?1:0;transformedGames.push(g);}
  // Fail closed on collisions: migration never overwrites existing v3 records.
  const locals=await DB.listGames();const localIds=new Set(locals.map(g=>g.id));const collision=transformedGames.find(g=>localIds.has(g.id));if(collision){const receipt={id:'legacyFoundationMigrationReceipt',status:'BLOCKED_CONFLICT',at:nowIso(),gameId:collision.id};await DB.setSetting('legacyFoundationMigrationReceipt',receipt);throw new RecordError(ERR.DB_MIGRATION,`Legacy migration blocked because game ${collision.id} already exists in the v3 database.`);}
  await withTx(['games','sourcePages','derivedAssets','auditEvents','settings'],'readwrite',async tx=>{for(const g of transformedGames){validateGame(g);tx.objectStore('games').put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'MIGRATED_FOUNDATION_V1_TO_V3',{sourcePages:transformedPages.filter(p=>p.gameId===g.id).length,legacyDatabase:APP.legacyDbName},'SYSTEM'));}for(const p of transformedPages){validateSourcePage(p);tx.objectStore('sourcePages').put(p);}for(const a of derived){validateDerivedAsset(a);tx.objectStore('derivedAssets').put(a);}tx.objectStore('settings').put({id:'legacyFoundationMigrationReceipt',value:{status:'COMPLETE',at:nowIso(),games:transformedGames.length,pages:transformedPages.length,legacyDatabaseRetained:true}});});
  return {status:'COMPLETE',games:transformedGames.length,pages:transformedPages.length,legacyDatabaseRetained:true};
}

function validateStoreObject(name,obj){if(name==='games')return validateGame(obj);if(name==='sourcePages')return validateSourcePage(obj);if(name==='derivedAssets')return validateDerivedAsset(obj);if(name==='recognitionJobs')return validateRecognitionJob(obj);if(name==='recognitionObservations')return validateRecognitionEnvelope(obj);if(name==='reconstructionRuns')return validateReconstructionRun(obj);if(name==='auditEvents')return validateAuditEvent(obj);return true;}

async function preflightRestoreCollisions(snapshot,conflict){
  const db=await openDb(),collisions=[];const ownership={sourcePages:'gameId',derivedAssets:'gameId',recognitionJobs:'gameId',recognitionObservations:'gameId',reconstructionRuns:'gameId',auditEvents:'gameId'};
  for(const [storeName,ownerKey] of Object.entries(ownership)){const store=db.transaction(storeName,'readonly').objectStore(storeName);for(const incoming of snapshot[storeName]||[]){const key=storeName==='recognitionObservations'?incoming.requestId:incoming.id,local=await request(store.get(key));if(local&&local[ownerKey]!==incoming[ownerKey])collisions.push({store:storeName,key,localGameId:local[ownerKey],incomingGameId:incoming[ownerKey]});}}
  if(collisions.length)throw new RecordError(ERR.IMP_CONFLICT,'Restore would overwrite dependent objects belonging to other local games.',{collisions});
  return true;
}

export const DB={
  onState(fn){listeners.add(fn);return()=>listeners.delete(fn);},
  async init(){await openDb();await normalizeV2ToV3();const migration=await commissionLegacyMigration();await this.reconcileRecognitionJobs();return {migration};},
  async createGame(){const game=createGame();await withTx(['games','auditEvents'],'readwrite',async tx=>{tx.objectStore('games').put(game);putAudit(tx.objectStore('auditEvents'),auditEvent(game,'GAME_CREATED',{},'USER'));});return game;},
  async getGame(id){const db=await openDb(),g=await request(db.transaction('games','readonly').objectStore('games').get(id));if(!g)return null;validateGame(g);return g;},
  async listGames(){const db=await openDb(),games=await request(db.transaction('games','readonly').objectStore('games').getAll());games.forEach(validateGame);return games.sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt)));},
  async pages(gameId){const db=await openDb(),pages=await getAll(db.transaction('sourcePages','readonly').objectStore('sourcePages'),'gameId',gameId);pages.forEach(validateSourcePage);return pages.sort((a,b)=>a.order-b.order);},
  async sourceBytes(gameId){return (await this.pages(gameId)).reduce((n,p)=>n+p.size,0);},
  async mutateGame(gameId,{eventType='GAME_UPDATED',payload={},evidenceBearing=true,actor='USER'}={},mutator){return withTx(['games','auditEvents'],'readwrite',async tx=>{const games=tx.objectStore('games'),audits=tx.objectStore('auditEvents'),game=await request(games.get(gameId));if(!game)throw new RecordError(ERR.DB_SCHEMA,'Game not found.');validateGame(game);const before=game.revision,inv=evidenceBearing?invalidateCertification(game,eventType):{invalidated:false};await mutator(game);game.revision=evidenceBearing?before+1:before;game.updatedAt=nowIso();validateGame(game);games.put(game);putAudit(audits,auditEvent(game,eventType,{...payload,certificationInvalidated:inv.invalidated},actor));return game;});},
  async commitCertification(gameId,{expectedRevision,expectedSourceRevision,certification}){return withTx(['games','auditEvents'],'readwrite',async tx=>{const store=tx.objectStore('games'),g=await request(store.get(gameId));validateGame(g);if(g.revision!==expectedRevision||g.sourceRevision!==expectedSourceRevision)throw new RecordError(ERR.CERT_REVISION,'Record changed while certification was being prepared. Re-review before certifying.');g.certification=certification;g.certificationStatus='VALID';g.workflowState='COMPLETE';g.updatedAt=nowIso();validateGame(g);store.put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'CERTIFICATION_CREATED',{canonicalHash:certification.canonicalHash,observationRoot:certification.observationRoot},'USER'));return g;});},
  async addPage(gameId,page,derivedAssets=[]){return withTx(['games','sourcePages','derivedAssets','auditEvents'],'readwrite',async tx=>{const games=tx.objectStore('games'),sources=tx.objectStore('sourcePages'),derived=tx.objectStore('derivedAssets'),g=await request(games.get(gameId));validateGame(g);const existing=await getAll(sources,'gameId',gameId);page.order=existing.length;validateSourcePage(page);invalidateCertification(g,'SOURCE_ADDED');g.sourceRevision++;g.revision++;g.updatedAt=nowIso();g.workflowState='CAPTURED';g.flags.needsReview=false;sources.put(page);for(const a of derivedAssets){validateDerivedAsset(a);derived.put(a);}games.put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'SOURCE_ADDED',{pageId:page.id,sha256:page.sha256,derivedAssetIds:derivedAssets.map(x=>x.id)}));return g;});},
  async deletePage(gameId,pageId){return withTx(['games','sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents'],'readwrite',async tx=>{const games=tx.objectStore('games'),sources=tx.objectStore('sourcePages'),g=await request(games.get(gameId));validateGame(g);const pages=(await getAll(sources,'gameId',gameId)).sort((a,b)=>a.order-b.order),target=pages.find(p=>p.id===pageId);if(!target)return g;sources.delete(pageId);for(const name of ['derivedAssets','recognitionJobs','recognitionObservations'])for(const o of await getAll(tx.objectStore(name),'gameId',gameId))if((o.sourcePageId||o.pageId)===pageId)tx.objectStore(name).delete(name==='recognitionObservations'?o.requestId:o.id);for(const r of await getAll(tx.objectStore('reconstructionRuns'),'gameId',gameId))tx.objectStore('reconstructionRuns').delete(r.id);pages.filter(p=>p.id!==pageId).forEach((p,i)=>{p.order=i;p.updatedAt=nowIso();sources.put(p);});invalidateCertification(g,'SOURCE_REMOVED');g.sourceRevision++;g.revision++;g.updatedAt=nowIso();g.flags.needsReview=true;games.put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'SOURCE_REMOVED',{pageId}));return g;});},
  async reorderPage(gameId,pageId,delta){return withTx(['games','sourcePages','reconstructionRuns','auditEvents'],'readwrite',async tx=>{const games=tx.objectStore('games'),sources=tx.objectStore('sourcePages'),g=await request(games.get(gameId));validateGame(g);const pages=(await getAll(sources,'gameId',gameId)).sort((a,b)=>a.order-b.order),i=pages.findIndex(p=>p.id===pageId),j=Math.max(0,Math.min(pages.length-1,i+delta));if(i<0||i===j)return g;[pages[i],pages[j]]=[pages[j],pages[i]];pages.forEach((p,k)=>{p.order=k;p.updatedAt=nowIso();sources.put(p);});for(const r of await getAll(tx.objectStore('reconstructionRuns'),'gameId',gameId))tx.objectStore('reconstructionRuns').delete(r.id);invalidateCertification(g,'SOURCE_REORDERED');g.sourceRevision++;g.revision++;g.updatedAt=nowIso();g.flags.needsReview=true;games.put(g);putAudit(tx.objectStore('auditEvents'),auditEvent(g,'SOURCE_REORDERED',{pageId,from:i,to:j}));return g;});},
  async derivedForPage(gameId,pageId){const db=await openDb(),all=await getAll(db.transaction('derivedAssets','readonly').objectStore('derivedAssets'),'gameId',gameId);return all.filter(a=>a.sourcePageId===pageId).map(a=>(validateDerivedAsset(a),a));},
  async jobs(gameId=null){const db=await openDb(),store=db.transaction('recognitionJobs','readonly').objectStore('recognitionJobs'),out=gameId?await getAll(store,'gameId',gameId):await getAll(store);out.forEach(validateRecognitionJob);return out.sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt)));},
  async putJob(job){validateRecognitionJob(job);return withTx(['recognitionJobs'],'readwrite',tx=>{tx.objectStore('recognitionJobs').put(job);return job;});},
  async commitRecognitionResult(env,job){validateRecognitionEnvelope(env);validateRecognitionJob(job);if(env.requestId!==job.id||env.gameId!==job.gameId||env.pageId!==job.pageId||env.runSequence!==job.runSequence)throw new RecordError(ERR.VIS_BINDING,'Recognition result does not bind to its job.');return withTx(['recognitionObservations','recognitionJobs'],'readwrite',async tx=>{const obs=tx.objectStore('recognitionObservations'),jobs=tx.objectStore('recognitionJobs'),prior=await request(obs.get(env.requestId));if(prior&&JSON.stringify(prior)!==JSON.stringify(env))throw new RecordError(ERR.DB_CONFLICT,'Recognition observations are immutable; request ID already exists with different content.');if(!prior)obs.add(env);jobs.put(job);return job;});},
  async supersedePriorRecognitionJobs(gameId,pageId,currentId,currentSequence){return withTx(['recognitionJobs'],'readwrite',async tx=>{const store=tx.objectStore('recognitionJobs'),jobs=(await getAll(store,'gameId',gameId)).filter(j=>j.pageId===pageId&&j.id!==currentId&&j.runSequence<currentSequence&&j.status==='COMPLETE');for(const j of jobs)store.put({...j,status:'SUPERSEDED',updatedAt:nowIso()});return jobs.length;});},
  async nextRunSequence(gameId,pageId){const js=(await this.jobs(gameId)).filter(j=>j.pageId===pageId);return js.reduce((m,j)=>Math.max(m,j.runSequence||0),0)+1;},
  async observations(gameId=null){const db=await openDb(),store=db.transaction('recognitionObservations','readonly').objectStore('recognitionObservations'),out=gameId?await getAll(store,'gameId',gameId):await getAll(store);out.forEach(validateRecognitionEnvelope);return out.sort((a,b)=>(a.pageId.localeCompare(b.pageId)||a.runSequence-b.runSequence||a.requestId.localeCompare(b.requestId)));},
  async putObservation(env){validateRecognitionEnvelope(env);return withTx(['recognitionObservations'],'readwrite',async tx=>{const s=tx.objectStore('recognitionObservations'),prior=await request(s.get(env.requestId));if(prior){if(JSON.stringify(prior)!==JSON.stringify(env))throw new RecordError(ERR.DB_CONFLICT,'Recognition observations are immutable; request ID already exists with different content.');return prior;}s.add(env);return env;});},
  async currentObservations(gameId){const obs=await this.observations(gameId),jobs=await this.jobs(gameId),current=new Map();for(const j of jobs.filter(j=>j.status==='COMPLETE').sort((a,b)=>a.runSequence-b.runSequence||a.updatedAt.localeCompare(b.updatedAt)))current.set(j.pageId,j.id);return obs.filter(o=>current.get(o.pageId)===o.requestId).sort((a,b)=>a.pageId.localeCompare(b.pageId)||a.runSequence-b.runSequence||a.requestId.localeCompare(b.requestId));},
  async putReconstruction(run){validateReconstructionRun(run);return withTx(['reconstructionRuns'],'readwrite',tx=>{tx.objectStore('reconstructionRuns').put(run);return run;});},
  async reconstructions(gameId){const db=await openDb(),out=await getAll(db.transaction('reconstructionRuns','readonly').objectStore('reconstructionRuns'),'gameId',gameId);out.forEach(validateReconstructionRun);return out.sort((a,b)=>String(b.createdAt).localeCompare(String(a.createdAt)));},
  async audit(gameId){const db=await openDb(),out=await getAll(db.transaction('auditEvents','readonly').objectStore('auditEvents'),'gameId',gameId);out.forEach(validateAuditEvent);return out.sort((a,b)=>String(a.timestamp).localeCompare(String(b.timestamp)));},
  async reconcileRecognitionJobs(){const jobs=await this.jobs(),obs=await this.observations(),obsIds=new Set(obs.map(o=>o.requestId)),now=Date.now();let changed=0;for(let j of jobs){if(['UPLOADING','PROCESSING'].includes(j.status)&&now-Date.parse(j.updatedAt)>LIMITS.staleRecognitionMs){j={...j,status:obsIds.has(j.id)?'COMPLETE':'FAILED_RETRYABLE',updatedAt:nowIso(),lastError:obsIds.has(j.id)?null:'REC-VIS-007: interrupted recognition recovered after foreground/restart.',nextAttemptAt:obsIds.has(j.id)?null:nowIso()};await this.putJob(j);changed++;}}return changed;},
  async deriveJobFlags(gameId){const jobs=await this.jobs(gameId);return {hasFailedJob:jobs.some(j=>['FAILED_RETRYABLE','FAILED_TERMINAL'].includes(j.status)),offlineQueue:jobs.some(j=>['QUEUED','FAILED_RETRYABLE'].includes(j.status))};},
  async getSetting(id,fallback=null){const db=await openDb(),x=await request(db.transaction('settings','readonly').objectStore('settings').get(id));return x?.value??fallback;},
  async setSetting(id,value){return withTx(['settings'],'readwrite',tx=>{tx.objectStore('settings').put({id,value});return value;});},
  async getDeviceKey(){const db=await openDb();return request(db.transaction('deviceKeys','readonly').objectStore('deviceKeys').get('device'));},
  async setDeviceKey(value){return withTx(['deviceKeys'],'readwrite',tx=>{tx.objectStore('deviceKeys').put(value);return value;});},
  async deleteGame(gameId){return withTx(STORES.filter(x=>x!=='settings'&&x!=='deviceKeys'),'readwrite',async tx=>{tx.objectStore('games').delete(gameId);for(const name of ['sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents'])for(const o of await getAll(tx.objectStore(name),'gameId',gameId))tx.objectStore(name).delete(name==='recognitionObservations'?o.requestId:o.id);});},
  async snapshot(){const db=await openDb(),tx=db.transaction(STORES.filter(x=>x!=='deviceKeys'),'readonly'),out={};for(const name of STORES.filter(x=>x!=='deviceKeys'))out[name]=await request(tx.objectStore(name).getAll());return out;},
  async restoreSnapshot(snapshot,{conflict='KEEP_LOCAL'}={}){
    if(!['KEEP_LOCAL','REPLACE_LOCAL','SKIP'].includes(conflict))throw new RecordError(ERR.IMP_CONFLICT,'Unsupported restore conflict policy.');await preflightRestoreCollisions(snapshot,conflict);
    return withTx(STORES.filter(x=>x!=='deviceKeys'),'readwrite',async tx=>{const games=tx.objectStore('games'),incoming=snapshot.games||[],importIds=new Set();for(const g of incoming){validateGame(g);const local=await request(games.get(g.id));if(local&&['KEEP_LOCAL','SKIP'].includes(conflict))continue;if(local&&conflict==='REPLACE_LOCAL')for(const name of ['sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents'])for(const o of await getAll(tx.objectStore(name),'gameId',g.id))tx.objectStore(name).delete(name==='recognitionObservations'?o.requestId:o.id);games.put(g);importIds.add(g.id);}for(const name of ['sourcePages','derivedAssets','recognitionJobs','recognitionObservations','reconstructionRuns','auditEvents'])for(const obj of snapshot[name]||[]){validateStoreObject(name,obj);if(importIds.has(obj.gameId))tx.objectStore(name).put(obj);}for(const obj of snapshot.settings||[])if(['lastBackupAt','gatewayPreferences','originCutoverReceipt'].includes(obj?.id))tx.objectStore('settings').put(obj);return {imported:[...importIds]};});
  },
};
